=<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #ffffff; color: #000000; margin: 0; padding: 0; }
        .wrapper { background-color: #ffffff; padding: 20px 10px; }
        .container { max-width: 600px; margin: 0 auto; border: 1px solid #000000; border-radius: 0; overflow: hidden; }
        .header { background: #000000; padding: 30px 10px; text-align: center; }
        .header-text { color: #ffffff; font-size: 20px; font-weight: 900; letter-spacing: 8px; text-transform: uppercase; }
        .content { padding: 40px 30px; }
        .badge { display: inline-block; padding: 5px 10px; border: 1px solid #000000; font-weight: 900; font-size: 11px; text-transform: uppercase; margin-bottom: 30px; }
        .title { font-size: 24px; font-weight: 900; color: #000000; margin: 0 0 20px; letter-spacing: -0.5px; }
        .alert-box { background: #f1f5f9; padding: 25px; margin-bottom: 35px; border-left: 5px solid #000000; }
        .description { font-size: 16px; color: #1e293b; line-height: 1.5; margin: 0; }
        .tech-table { width: 100%; border-collapse: collapse; margin-bottom: 35px; }
        .tech-row { border-bottom: 1px solid #e2e8f0; }
        .tech-label { padding: 15px 0; color: #64748b; font-size: 10px; font-weight: 800; text-transform: uppercase; width: 100px; }
        .tech-value { padding: 15px 0; color: #000000; font-size: 14px; font-weight: 700; }
        .btn { display: inline-block; background: #000000; color: #ffffff !important; text-decoration: none; padding: 15px 30px; font-weight: 800; font-size: 13px; text-transform: uppercase; letter-spacing: 1px; }
        .footer { padding: 20px; text-align: center; color: #94a3b8; font-size: 10px; border-top: 1px solid #e2e8f0; letter-spacing: 2px; text-transform: uppercase; }

        @media only screen and (max-width: 600px) {
            .content { padding: 25px 20px; }
            .btn { width: 100%; text-align: center; box-sizing: border-box; }
        }
    </style>
</head>
<body>
    <div class="wrapper">
        <div class="container">
            <div class="header">
                <div class="header-text">SISTEMA DE ALERTAS</div>
            </div>

            <div class="content">
                <div class="badge">
                    {{ {high:'ALTA', critical:'CRÍTICA', urgent:'URGENTE'}[($json.body?.severity || $json.severity || 'urgent').toLowerCase()] || 'ALTA' }}
                </div>

                <h2 class="title">Alerta de Seguridad</h2>

                <div class="alert-box">
                    <p class="description">{{ ($json.body?.description || $json.description || 'Evento detectado.') }}</p>
                </div>

                <table class="tech-table">
                    <tr class="tech-row">
                        <td class="tech-label">Cliente</td>
                        <td class="tech-value">{{ $json.body?.clientName || $json.clientName || 'Iberdrola S.A.' }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Incidente</td>
                        <td class="tech-value">{{ ($json.body?.title || $json.title || 'ALERTA SOS') }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">ID</td>
                        <td class="tech-value">#{{ $json.body?.alertId || $json.alertId || '5120' }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Timestamp</td>
                        <td class="tech-value">{{ $json.body?.timestamp || $json.timestamp }}</td>
                    </tr>
                </table>

                <div style="text-align: center;">
                    <a href="https://sofia-solutions.serveo.net" class="btn">ACCEDER AL PANEL</a>
                </div>
            </div>

            <div class="footer">
                CENTRO DE SEGURIDAD 24/7 | MONITOREO DE RED
            </div>
        </div>
    </div>
</body>
</html>
